schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "faion://claude-md-creation/output.schema.json",
  "title": "CLAUDE.md creation record",
  "type": "object",
  "required": [
    "repo", "layout", "template", "token_count", "commands", "secrets_scan", "structure",
    "key_files", "gotchas", "local_settings", "resync_check", "evidence"
  ],
  "additionalProperties": false,
  "definitions": {
    "path_with_purpose": {
      "type": "object",
      "required": ["path", "purpose"],
      "additionalProperties": false,
      "properties": {
        "path": {
          "type": "string",
          "minLength": 1,
          "not": {"pattern": "(^|/)(node_modules|dist|build|\\.venv|__pycache__|\\.next|target)(/|$)"}
        },
        "purpose": {"type": "string", "minLength": 5},
        "exists": {"type": "boolean"}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "repo": {"type": "string", "pattern": "^[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$"},
    "layout": {"type": "string", "enum": ["single", "monorepo"]},
    "template": {"type": "string", "enum": ["minimal", "standard", "monorepo"]},
    "token_count": {"type": "integer", "minimum": 1},
    "commands": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["command", "source", "comment", "ran_ok"],
        "additionalProperties": false,
        "properties": {
          "command": {"type": "string", "minLength": 2},
          "source": {"type": "string", "enum": ["package.json", "Makefile", "pyproject.toml", "justfile", "other-manifest"]},
          "comment": {"type": "string", "minLength": 3},
          "ran_ok": {"type": "boolean", "const": true}
        }
      }
    },
    "secrets_scan": {
      "type": "object",
      "required": ["tool", "clean", "env_vars_by_name_only", "env_example_referenced"],
      "additionalProperties": false,
      "properties": {
        "tool": {"type": "string", "enum": ["gitleaks", "trufflehog", "host-builtin"]},
        "clean": {"type": "boolean", "const": true},
        "env_vars_by_name_only": {"type": "boolean", "const": true},
        "env_example_referenced": {"type": "boolean", "const": true}
      }
    },
    "structure": {
      "type": "array",
      "minItems": 1,
      "maxItems": 20,
      "items": {"$ref": "#/definitions/path_with_purpose"}
    },
    "key_files": {
      "type": "array",
      "items": {
        "allOf": [
          {"$ref": "#/definitions/path_with_purpose"},
          {"type": "object", "required": ["exists"], "properties": {"exists": {"type": "boolean", "const": true}}}
        ]
      }
    },
    "gotchas": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["entry", "names"],
        "additionalProperties": false,
        "properties": {
          "entry": {
            "type": "string",
            "minLength": 15,
            "not": {"pattern": "(?i)^(write clean code|add tests|follow best practices|be careful)"}
          },
          "names": {"type": "string", "enum": ["file", "env-var", "command", "version-pin", "lint-rule"]}
        }
      }
    },
    "local_settings": {
      "type": "object",
      "required": ["personal_paths_grep_clean", "claude_local_md_gitignored"],
      "additionalProperties": false,
      "properties": {
        "personal_paths_grep_clean": {"type": "boolean", "const": true},
        "claude_local_md_gitignored": {"type": "boolean", "const": true}
      }
    },
    "resync_check": {
      "type": "object",
      "required": ["kind", "location", "fails_on_manifest_drift"],
      "additionalProperties": false,
      "properties": {
        "kind": {"type": "string", "enum": ["ci-job", "pre-commit-hook"]},
        "location": {"type": "string", "minLength": 3},
        "fails_on_manifest_drift": {"type": "boolean", "const": true}
      }
    },
    "monorepo": {
      "type": "object",
      "required": ["per_app_files", "root_restates_app_commands"],
      "additionalProperties": false,
      "properties": {
        "per_app_files": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["app", "path", "exists", "referenced_by"],
            "additionalProperties": false,
            "properties": {
              "app": {"type": "string", "minLength": 1},
              "path": {"type": "string", "pattern": "CLAUDE\\.md$"},
              "exists": {"type": "boolean", "const": true},
              "referenced_by": {"type": "string", "enum": ["import", "relative-path"]}
            }
          }
        },
        "root_restates_app_commands": {"type": "boolean", "const": false}
      }
    },
    "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "format": "uri"}}
  },
  "allOf": [
    {"if": {"properties": {"template": {"const": "minimal"}}}, "then": {"properties": {"token_count": {"maximum": 250}}}},
    {"if": {"properties": {"template": {"const": "standard"}}}, "then": {"properties": {"token_count": {"maximum": 500}}}},
    {"if": {"properties": {"template": {"const": "monorepo"}}}, "then": {"properties": {"token_count": {"maximum": 700}}}},
    {"if": {"properties": {"layout": {"const": "monorepo"}}}, "then": {"required": ["monorepo"], "properties": {"template": {"const": "monorepo"}}}}
  ]
}

output-contract.example:
{
  "repo": "acme/intake-api",
  "layout": "single",
  "template": "standard",
  "token_count": 3100,
  "commands": [
    {"command": "npm run test:unit", "source": "package.json", "comment": "Tests", "ran_ok": false}
  ],
  "secrets_scan": {"tool": "gitleaks", "clean": false, "env_vars_by_name_only": false, "env_example_referenced": false},
  "structure": [
    {"path": "node_modules/", "purpose": "dependencies"},
    {"path": "src/", "purpose": "code"},
    {"path": "dist/", "purpose": "build output"}
  ],
  "key_files": [
    {"path": "src/settings.py", "purpose": "Settings", "exists": false}
  ],
  "gotchas": [
    {"entry": "Write clean code and add tests", "names": "file"}
  ],
  "local_settings": {"personal_paths_grep_clean": false, "claude_local_md_gitignored": false},
  "resync_check": {"kind": "ci-job", "location": ".github/workflows/claude-md-sync.yml", "fails_on_manifest_drift": false},
  "evidence": [
    "https://ci.example.com/acme/intake-api/runs/8812"
  ]
}
